@DirtiesContext(classMode=DirtiesContext.ClassMode.AFTER_CLASS) @TestInstance(TestInstance.Lifecycle.PER_CLASS)
class EventsIT {
 static final String SCHEMA="it_events_"+UUID.randomUUID().toString().replace("-","");
 static final Path DIR=directory();static Path directory(){try{return Files.createTempDirectory("it_events_");}catch(IOException e){throw new UncheckedIOException(e);}}
 @DynamicPropertySource static void properties(DynamicPropertyRegistry p){p.add("spring.flyway.schemas",()->SCHEMA);p.add("spring.flyway.default-schema",()->SCHEMA);p.add("spring.datasource.hikari.connection-init-sql",()->"SET search_path TO "+SCHEMA);p.add("rallye.templates.image-directory",()->DIR.resolve("templates").toString());p.add("rallye.races.file-directory",()->DIR.resolve("events").toString());}
 @Autowired EventService events;@Autowired TemplateService templates;@Autowired TemplateImageService images;@Autowired TemplateFileService files;@Autowired EventFiles eventFiles;@Autowired TemplateImageFiles templateFiles;@Autowired JdbcTemplate jdbc;@Autowired AccountStore accounts;@Autowired MutableClock clock;@Autowired PlatformTransactionManager manager;@Autowired MockMvc mvc;@Autowired PreRaceAccountParticipationFacts facts;
 @MockitoSpyBean AuditStore audit;@MockitoSpyBean EventStore store;
 record Actor(UUID id,String token,AuthService.Principal principal){} Actor admin;
 TransactionTemplate tx(){return new TransactionTemplate(manager);}
 Actor actor(){return tx().execute(s->{UUID id=UUID.randomUUID();String email=id+"@example.test",token=new SecretTokens().create();Timestamp at=Timestamp.from(clock.instant());jdbc.update("INSERT INTO user_account(id,email,normalized_email,display_name,status,email_verified_at,created_at,updated_at) VALUES (?,?,?,'Test','ACTIVE',?,?,?)",id,email,email,at,at,at);jdbc.update("INSERT INTO user_identity(id,account_id,provider,issuer,subject,password_hash,created_at) VALUES (?,?,'LOCAL','local',?,'synthetic-test-hash',?)",UUID.randomUUID(),id,id.toString(),at);UUID session=accounts.insertSession(id,new SecretTokens().hash(token),false,clock.instant(),clock.instant().plusSeconds(86400));return new Actor(id,token,new AuthService.Principal(id,session,false));});}
 @BeforeAll void bootstrap()throws Exception{admin=actor();String sql=AdministrationIT.bootstrapBody(admin.id());tx().executeWithoutResult(s->jdbc.execute(sql));}
 @AfterAll void cleanup()throws Exception{assertTrue(SCHEMA.matches("it_events_[0-9a-f]{32}"));assertEquals("rallye_test",jdbc.queryForObject("SELECT current_database()",String.class));assertEquals("rallye_test",jdbc.queryForObject("SELECT current_user",String.class));jdbc.execute("DROP SCHEMA \""+SCHEMA+"\" CASCADE");assertTrue(DIR.getFileName().toString().startsWith("it_events_"));try(var all=Files.walk(DIR)){for(Path path:all.sorted(Comparator.reverseOrder()).toList())Files.delete(path);}}
 record Fixture(UUID template,UUID stage){}
 long version(UUID template){return templates.detail(admin.principal(),template).version();}
 Fixture ready()throws Exception{
  UUID template=templates.create(admin.principal(),UUID.randomUUID(),"Source",null,-3).id();UUID stage=templates.createStage(admin.principal(),template,0,UUID.randomUUID(),"Station",60000L,10L).id();
  String source="![Map]("+ImageNames.url(template,"map.png")+") [Guide]("+ImageNames.fileUrl(template,"guide.md")+"#part) [relative](rules.pdf)";
  templates.updateStage(admin.principal(),template,stage,1,"Station",60000L,10L,true,source);
  templates.configure(admin.principal(),template,stage,2,new TemplateService.ConfigurationChange(new Gps(true,50d,14d,100d,-1L,2L),new TemplateService.CodeChange(true,"synthetic-code",-2L),new TimePenalty(true,60000L,3L),new cz.mh.rallye.rallye_backend.templates.domain.StageConfiguration.Delayed(true,1000L,-1L)));
  byte[] png=cz.mh.rallye.rallye_backend.crews.PhotoFilesTest.image("png",2,2);upload(template,"map.png",png);
  try(var pdf=new org.apache.pdfbox.pdmodel.PDDocument();var out=new ByteArrayOutputStream()){pdf.addPage(new org.apache.pdfbox.pdmodel.PDPage());pdf.save(out);upload(template,"rules.pdf",out.toByteArray());}
  upload(template,"guide.md",("# Part\n\n[Self](guide.md) [Rules](rules.pdf) ![Map]("+ImageNames.url(template,"map.png")+")").getBytes(java.nio.charset.StandardCharsets.UTF_8));
  templates.state(admin.principal(),template,version(template),"READY");return new Fixture(template,stage);
 }
 void upload(UUID template,String name,byte[] data){files.upload(admin.principal(),template,version(template),UUID.randomUUID(),name,new ByteArrayInputStream(data));}
 EventService.Input input(String name){return new EventService.Input(name,null,Instant.parse("2026-11-01T10:00:00Z"),Instant.parse("2026-11-01T16:00:00Z"));}
 EventService.Created create(Fixture f){return events.create(admin.principal(),f.template(),version(f.template()),UUID.randomUUID(),input("Event-"+UUID.randomUUID()));}
 long count(String sql,Object... args){return jdbc.queryForObject(sql,Long.class,args);}
 long physicalFiles()throws IOException{if(!Files.exists(DIR.resolve("events")))return 0;try(var all=Files.walk(DIR.resolve("events"))){return all.filter(Files::isRegularFile).filter(p->!p.getFileName().toString().equals(".storage.lock")).count();}}
 @Test void readySnapshotIncludesAllRulesAndNoSecretsInHttp()throws Exception{var f=ready();long sourceVersion=version(f.template());var created=create(f);var detail=events.detail(admin.principal(),created.id());assertEquals("PLANNED",detail.status());assertEquals(f.template(),detail.sourceTemplateId());assertEquals(sourceVersion,detail.sourceTemplateVersion());assertEquals(-3,detail.skipPenaltyPoints());var s=events.stages(admin.principal(),created.id()).getFirst();assertNotEquals(f.stage(),s.id());assertEquals(f.stage(),s.sourceTemplateStageId());assertTrue(s.gps().enabled());assertTrue(s.code().enabled());assertTrue(s.code().codeConfigured());assertEquals(3,s.timePenalty().pointsPerInterval());assertEquals(-1,s.delayed().pointsPerSecond());assertEquals(jdbc.queryForObject("SELECT code_hash FROM template_stage WHERE id=?",String.class,f.stage()),jdbc.queryForObject("SELECT code_hash FROM event_stage WHERE id=?",String.class,s.id()));assertEquals(3,events.files(admin.principal(),created.id()).size());assertFalse(s.instructionsMarkdown().contains(f.template().toString()));assertTrue(s.instructionsMarkdown().contains("[relative](rules.pdf)"));assertTrue(s.instructionsRenderedHtml().contains("/race-events/"+created.id()));String response=mvc.perform(get("/api/v1/race-events/"+created.id()+"/stages").header("Authorization","Bearer "+admin.token())).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();assertFalse(response.contains("synthetic-code"));assertFalse(response.contains("$argon2"));assertEquals(1,count("SELECT count(*) FROM audit_event WHERE target_id=? AND event_type='RACE_EVENT_CREATED'",created.id()));}
 @Test void draftMissingAndStaleSourcesAreRejected()throws Exception{UUID draft=templates.create(admin.principal(),UUID.randomUUID(),"Draft",null,0).id();assertEquals("TEMPLATE_NOT_READY",assertThrows(AuthFailure.class,()->events.create(admin.principal(),draft,0,UUID.randomUUID(),input("Event"))).code());assertEquals(404,assertThrows(AuthFailure.class,()->events.create(admin.principal(),UUID.randomUUID(),0,UUID.randomUUID(),input("Event"))).status());var f=ready();assertEquals("TEMPLATE_VERSION_CONFLICT",assertThrows(AuthFailure.class,()->events.create(admin.principal(),f.template(),version(f.template())-1,UUID.randomUUID(),input("Event"))).code());}
 @Test void sourceChangesAndFileDeletionDoNotModifySnapshot()throws Exception{var f=ready();var created=create(f);var before=events.stages(admin.principal(),created.id());byte[] saved=events.file(admin.principal(),created.id(),"map.png").bytes();templates.updateStage(admin.principal(),f.template(),f.stage(),version(f.template()),"Changed",0L,0L,true,"New text");files.delete(admin.principal(),f.template(),"guide.md",version(f.template()));files.delete(admin.principal(),f.template(),"map.png",version(f.template()));templates.deleteStage(admin.principal(),f.template(),f.stage(),version(f.template()));assertEquals(before,events.stages(admin.principal(),created.id()));assertArrayEquals(saved,events.file(admin.principal(),created.id(),"map.png").bytes());assertTrue(new String(events.file(admin.principal(),created.id(),"guide.md").bytes(),java.nio.charset.StandardCharsets.UTF_8).contains(created.id().toString()));}
 @Test void eventFilesArePrivateAndCrossNamespaceLookupFails()throws Exception{var f=ready();var a=create(f);var b=create(f);assertEquals(404,assertThrows(AuthFailure.class,()->events.file(admin.principal(),a.id(),"absent.pdf")).status());assertThrows(AuthFailure.class,()->events.file(admin.principal(),a.id(),"../map.png"));mvc.perform(get("/api/v1/race-events/"+a.id()+"/files/rules.pdf").header("Authorization","Bearer "+admin.token())).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(header().string("Content-Disposition",org.hamcrest.Matchers.startsWith("attachment")));assertArrayEquals(events.file(admin.principal(),a.id(),"map.png").bytes(),events.file(admin.principal(),b.id(),"map.png").bytes());assertTrue(Files.exists(DIR.resolve("events/race-events/"+a.id()+"/images/map.png")));assertTrue(Files.exists(DIR.resolve("events/race-events/"+b.id()+"/images/map.png")));var ordinary=actor();assertEquals(403,assertThrows(AuthFailure.class,()->events.file(ordinary.principal(),a.id(),"map.png")).status());}
 @Test void idempotentReplayWorksAfterSourceChangeAndConflictDoesNotCreate()throws Exception{var f=ready();long v=version(f.template());UUID key=UUID.randomUUID();var request=input("Replay");var first=events.create(admin.principal(),f.template(),v,key,request);templates.update(admin.principal(),f.template(),v,"Changed",null,0);assertEquals(first,events.create(admin.principal(),f.template(),v,key,request));assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(AuthFailure.class,()->events.create(admin.principal(),f.template(),v,key,input("Other"))).code());assertEquals(1,count("SELECT count(*) FROM race_event WHERE source_template_id=?",f.template()));assertEquals(1,count("SELECT count(*) FROM audit_event WHERE target_id=? AND event_type='RACE_EVENT_CREATED'",first.id()));}
 @Test void editsAreVersionedAndNoOpHasNoAudit()throws Exception{var f=ready();var c=create(f);var before=events.detail(admin.principal(),c.id());assertEquals(before,events.update(admin.principal(),c.id(),0,new EventService.Input(before.name(),before.description(),before.scheduledStartAt(),before.endAt())));assertEquals(0,count("SELECT count(*) FROM audit_event WHERE target_id=? AND event_type='RACE_EVENT_UPDATED'",c.id()));assertEquals(1,events.update(admin.principal(),c.id(),0,input("Edited")).version());assertEquals("RACE_EVENT_VERSION_CONFLICT",assertThrows(AuthFailure.class,()->events.update(admin.principal(),c.id(),0,input("Old"))).code());assertEquals(1,count("SELECT count(*) FROM audit_event WHERE target_id=? AND event_type='RACE_EVENT_UPDATED'",c.id()));}
 @Test void usedTemplateCannotBeDeletedAndUnusedTemplateCan()throws Exception{var f=ready();create(f);assertEquals("TEMPLATE_IN_USE",assertThrows(AuthFailure.class,()->templates.delete(admin.principal(),f.template(),version(f.template()))).code());assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->jdbc.update("DELETE FROM race_template WHERE id=?",f.template()));UUID unused=templates.create(admin.principal(),UUID.randomUUID(),"Unused",null,0).id();templates.delete(admin.principal(),unused,0);assertEquals(0,count("SELECT count(*) FROM race_template WHERE id=?",unused));assertFalse(tx().execute(s->facts.forAccount(admin.id())).historical());}
 @Test void missingPhysicalSourceFileRollsBackAllData()throws Exception{var f=ready();templateFiles.files.exclusive(()->{templateFiles.remove(f.template(),"map.png");return null;});UUID key=UUID.randomUUID();long bytes=physicalFiles();assertThrows(AuthFailure.class,()->events.create(admin.principal(),f.template(),version(f.template()),key,input("Fail")));assertEquals(0,count("SELECT count(*) FROM race_event WHERE source_template_id=?",f.template()));assertEquals(0,count("SELECT count(*) FROM admin_role_command WHERE command_key=?",key));assertEquals(bytes,physicalFiles());}
 @Test void corruptedSourceContentIsNotCopied()throws Exception{var f=ready();templateFiles.files.exclusive(()->{templateFiles.remove(f.template(),"map.png");templateFiles.write(f.template(),"map.png",new byte[]{1,2,3});return null;});assertThrows(AuthFailure.class,()->create(f));assertEquals(0,count("SELECT count(*) FROM race_event WHERE source_template_id=?",f.template()));}
 @Test void auditFailureRollsBackEventStagesFilesLedgerAndCanRetry()throws Exception{var f=ready();UUID key=UUID.randomUUID();long bytes=physicalFiles();var fail=new AtomicBoolean(true);doAnswer(i->{Object value=i.callRealMethod();if(fail.get())throw new IllegalStateException("Injected after audit insert");return value;}).when(audit).appendRace(any(),any(),any(),eq(Event.RACE_EVENT_CREATED),any(),eq(f.template()),anyLong());assertThrows(RuntimeException.class,()->events.create(admin.principal(),f.template(),version(f.template()),key,input("Retry")));assertEquals(0,count("SELECT count(*) FROM race_event WHERE source_template_id=?",f.template()));assertEquals(0,count("SELECT count(*) FROM admin_role_command WHERE command_key=?",key));assertEquals(0,count("SELECT count(*) FROM audit_event WHERE event_type='RACE_EVENT_CREATED' AND metadata->>'sourceTemplateId'=?",f.template().toString()));assertEquals(bytes,physicalFiles());fail.set(false);assertNotNull(events.create(admin.principal(),f.template(),version(f.template()),key,input("Retry")));}
 List<String> race(Callable<String> first,Callable<String> second)throws Exception{var barrier=new CyclicBarrier(2);try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->{barrier.await(10,TimeUnit.SECONDS);return first.call();});var b=pool.submit(()->{barrier.await(10,TimeUnit.SECONDS);return second.call();});return List.of(a.get(30,TimeUnit.SECONDS),b.get(30,TimeUnit.SECONDS));}}
 @Test void concurrentCreationAndSourceChangeCannotMixSnapshots()throws Exception{var f=ready();long v=version(f.template());var result=race(()->{try{return events.create(admin.principal(),f.template(),v,UUID.randomUUID(),input("Concurrent")).id().toString();}catch(AuthFailure e){return e.code();}},()->{templates.updateStage(admin.principal(),f.template(),f.stage(),v,"Changed",500L,20L,true,"New instructions");return "UPDATED";});assertEquals("UPDATED",result.getLast());if(result.getFirst().equals("TEMPLATE_VERSION_CONFLICT")){assertEquals(0,count("SELECT count(*) FROM race_event WHERE source_template_id=?",f.template()));}else{var copied=events.stages(admin.principal(),UUID.fromString(result.getFirst())).getFirst();assertEquals("Station",copied.name());assertEquals(60000,copied.expectedDurationMs());assertEquals(10,copied.maxPenaltyPoints());assertFalse(copied.instructionsMarkdown().contains("New instructions"));}}
 @Test void concurrentSameKeyCreatesOneSnapshotAndAudit()throws Exception{var f=ready();long v=version(f.template());UUID key=UUID.randomUUID();Callable<String> create=()->events.create(admin.principal(),f.template(),v,key,input("Same")).id().toString();var result=race(create,create);assertEquals(result.getFirst(),result.getLast());assertEquals(1,count("SELECT count(*) FROM race_event WHERE source_template_id=?",f.template()));assertEquals(1,count("SELECT count(*) FROM audit_event WHERE target_id=? AND event_type='RACE_EVENT_CREATED'",UUID.fromString(result.getFirst())));}
 @Test void concurrentSourceDeletionCannotRemoveSourceOfCreatedEvent()throws Exception{var f=ready();long v=version(f.template());var result=race(()->{try{return events.create(admin.principal(),f.template(),v,UUID.randomUUID(),input("Race")).id().toString();}catch(AuthFailure e){return e.code();}},()->{try{templates.delete(admin.principal(),f.template(),v);return "DELETED";}catch(AuthFailure e){return e.code();}});if(result.getLast().equals("DELETED")){assertEquals("TEMPLATE_NOT_FOUND",result.getFirst());assertEquals(0,count("SELECT count(*) FROM race_event WHERE source_template_id=?",f.template()));}else{assertEquals("TEMPLATE_IN_USE",result.getLast());assertNotNull(events.detail(admin.principal(),UUID.fromString(result.getFirst())));}}
 @Test void unknownMigrationFailsClosedButReviewedV21IsAccepted(){assertEquals(1,count("SELECT count(*) FROM flyway_schema_history WHERE version='21' AND script='V21__planned_race_events.sql' AND success"));tx().executeWithoutResult(s->{assertFalse(facts.forAccount(admin.id()).running());jdbc.update("UPDATE flyway_schema_history SET script='V21__unknown.sql' WHERE version='21'");assertEquals(503,assertThrows(AuthFailure.class,()->facts.forAccount(admin.id())).status());s.setRollbackOnly();});}
 @Test void pagingAndSearchRemainScopedAndAdminOnly()throws Exception{var f=ready();String term="unique-"+UUID.randomUUID();var a=events.create(admin.principal(),f.template(),version(f.template()),UUID.randomUUID(),input(term+"-a"));events.create(admin.principal(),f.template(),version(f.template()),UUID.randomUUID(),input(term+"-b"));var first=events.list(admin.principal(),term,0,1);var second=events.list(admin.principal(),term,1,1);assertEquals(1,first.items().size());assertTrue(first.hasMore());assertFalse(second.hasMore());assertNotEquals(first.items().getFirst().id(),second.items().getFirst().id());var ordinary=actor();mvc.perform(get("/api/v1/race-events/"+a.id()).header("Authorization","Bearer "+ordinary.token())).andExpect(status().isForbidden());mvc.perform(get("/api/v1/race-events/"+a.id())).andExpect(status().isUnauthorized());}
 @Test void updateAuditFailureRestoresNameVersionAndTimestamp()throws Exception{var f=ready();var created=create(f);var before=events.detail(admin.principal(),created.id());var fail=new AtomicBoolean(true);doAnswer(i->{Object result=i.callRealMethod();if(fail.get())throw new IllegalStateException("Injected update audit failure");return result;}).when(audit).appendRace(any(),any(),any(),eq(Event.RACE_EVENT_UPDATED),eq(created.id()),any(),anyLong());assertThrows(RuntimeException.class,()->events.update(admin.principal(),created.id(),0,input("Failed edit")));assertEquals(before,events.detail(admin.principal(),created.id()));assertEquals(0,count("SELECT count(*) FROM audit_event WHERE target_id=? AND event_type='RACE_EVENT_UPDATED'",created.id()));fail.set(false);assertEquals(1,events.update(admin.principal(),created.id(),0,input("Retry edit")).version());}
 @Test void newCommandFormatSupportsPrivacyAndAuditRetention()throws Exception{var f=ready();var created=create(f);var cleanup=new cz.mh.rallye.rallye_backend.shared.persistence.CommandCleanupStore(jdbc,new cz.mh.rallye.rallye_backend.shared.persistence.CommandStore(jdbc));tx().executeWithoutResult(s->cleanup.prepareForAuditDeletion());tx().executeWithoutResult(s->cleanup.deleteRelated(admin.id(),"unused@example.test"));assertNotNull(events.detail(admin.principal(),created.id()));assertEquals(0,count("SELECT count(*) FROM admin_role_command WHERE actor_id=?",admin.id()));}
 @Test void upgradeV20ToV21PreservesTemplateDataAndCreatesEmptySnapshots(){String schema=SCHEMA+"_v21";assertTrue(schema.matches("it_events_[0-9a-f]{32}_v21"));var source=jdbc.getDataSource();UUID template=UUID.randomUUID(),stage=UUID.randomUUID();try{org.flywaydb.core.Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("20").load().migrate();jdbc.update("INSERT INTO "+schema+".race_template(id,name,skip_penalty_points,status,version,created_at,updated_at) VALUES (?,'Preserved',-3,'READY',7,now(),now())",template);jdbc.update("INSERT INTO "+schema+".template_stage(id,race_template_id,sequence_no,name,instructions_markdown,code_enabled,code_hash,wrong_code_penalty_points) VALUES (?,?,1,'Station','Text',true,'synthetic-test-hash',-5)",stage,template);var before=jdbc.queryForMap("SELECT id,race_template_id,name,instructions_markdown,code_hash FROM "+schema+".template_stage WHERE id=?",stage);org.flywaydb.core.Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("21").load().migrate();assertEquals(before,jdbc.queryForMap("SELECT id,race_template_id,name,instructions_markdown,code_hash FROM "+schema+".template_stage WHERE id=?",stage));assertEquals(7,count("SELECT version FROM "+schema+".race_template WHERE id=?",template));assertEquals(0,count("SELECT count(*) FROM "+schema+".race_event"));assertEquals(0,count("SELECT count(*) FROM "+schema+".event_stage"));assertEquals(0,count("SELECT count(*) FROM "+schema+".event_file"));}finally{jdbc.execute("DROP SCHEMA "+schema+" CASCADE");}}

}
